const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '第二象限' },
      { kind: 'text', payload: 'P(-3,2)' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: 'O' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var left = 70, right = 50, top = 50, bottom = 60;
    var scale = Math.min((W - left - right) / 13, (H - top - bottom) / 9);
    if (!(scale > 0)) scale = 20;
    var originX = left + 6.5 * scale;
    var originY = top + 4.5 * scale;
    function sx(x) { return originX + x * scale; }
    function sy(y) { return originY - y * scale; }
    function dashedLine(x1, y1, x2, y2, dash, gap) {
      var dx = x2 - x1, dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (len <= 0) return [];
      var ux = dx / len, uy = dy / len;
      var out = [];
      var pos = 0;
      while (pos < len) {
        var a = pos;
        var b = Math.min(pos + dash, len);
        var ax = x1 + ux * a, ay = y1 + uy * a;
        var bx = x1 + ux * b, by = y1 + uy * b;
        out = out.concat(visualSdk.polyline([[ax, ay], [bx, by]]));
        pos += dash + gap;
      }
      return out;
    }
    var axisLeft = sx(-6.2), axisRight = sx(6.2);
    var axisTop = sy(4.2), axisBottom = sy(-4.2);
    var xAxis = visualSdk.arrow(axisLeft, originY, axisRight, originY, {});
    var yAxis = visualSdk.arrow(originX, axisBottom, originX, axisTop, {});
    var ticks = [];
    for (var i = -6; i <= 6; i++) {
      if (i === 0) continue;
      var tx = sx(i);
      ticks = ticks.concat(visualSdk.polyline([[tx, originY - 3], [tx, originY + 3]]));
    }
    for (var j = -4; j <= 4; j++) {
      if (j === 0) continue;
      var ty = sy(j);
      ticks = ticks.concat(visualSdk.polyline([[originX - 3, ty], [originX + 3, ty]]));
    }
    var px = sx(-3), py = sy(2);
    var dot = visualSdk.circle(px, py, 5);
    var dashes = dashedLine(px, py, px, originY, 7, 5)
      .concat(dashedLine(px, py, originX, py, 7, 5));
    var qx = sx(-4.8), qy = sy(3.5);
    var pLabelX = px + 10, pLabelY = py - 10;
    var xLabelX = axisRight - 2, xLabelY = originY - 9;
    var yLabelX = originX + 9, yLabelY = axisTop + 4;
    var oLabelX = originX - 8, oLabelY = originY + 17;
    if (metrics && metrics[0] && typeof metrics[0].width === 'number') {
      qx = Math.max(sx(-5.6) + metrics[0].width / 2, qx);
    }
    var scene = {
      schemaVersion: 1,
      sceneId: 'point-p-second-quadrant',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'x-axis', commands: xAxis },
        { id: 'y-axis', commands: yAxis },
        { id: 'ticks', commands: ticks },
        { id: 'dashes', commands: dashes },
        { id: 'point', commands: dot }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'x-axis', stroke: '#26354a', strokeWidth: 1.4, fill: 'none' },
          { type: 'path', pathId: 'y-axis', stroke: '#26354a', strokeWidth: 1.4, fill: 'none' },
          { type: 'path', pathId: 'ticks', stroke: '#26354a', strokeWidth: 1 },
          { type: 'path', pathId: 'dashes', stroke: '#d9480f', strokeWidth: 1.5, fill: 'none' },
          { type: 'path', pathId: 'point', fill: '#d9480f', stroke: '#d9480f', strokeWidth: 1 },
          { type: 'label', x: qx, y: qy, text: '第二象限', fontSize: 14, fill: '#d9480f', anchor: 'middle', textAnchor: 'middle' },
          { type: 'label', x: pLabelX, y: pLabelY, text: 'P(-3,2)', fontSize: 14, fill: '#d9480f', anchor: 'start', textAnchor: 'start' },
          { type: 'label', x: xLabelX, y: xLabelY, text: 'x', fontSize: 14, fill: '#26354a', anchor: 'end', textAnchor: 'end' },
          { type: 'label', x: yLabelX, y: yLabelY, text: 'y', fontSize: 14, fill: '#26354a', anchor: 'start', textAnchor: 'start' },
          { type: 'label', x: oLabelX, y: oLabelY, text: 'O', fontSize: 13, fill: '#26354a', anchor: 'end', textAnchor: 'end' }
        ]
      }
    };
    return scene;
  }
};
